def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str) -> tuple:
        # Remove build metadata (everything after '+')
        v = v.split('+')[0]

        # Split into base version and pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            base = v
            prerelease_parts = None

        # Parse base version (major.minor.patch)
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre_a, pre_b):
        # No pre-release means higher precedence
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1  # a has no pre-release, so it's higher
        if pre_b is None:
            return -1  # b has no pre-release, so it's higher

        # Compare pre-release identifiers one by one
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                return -1  # a has fewer identifiers, so lower
            if i >= len(pre_b):
                return 1  # b has fewer identifiers, so a is higher

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_numeric_a = id_a.isdigit()
            is_numeric_b = id_b.isdigit()

            if is_numeric_a and is_numeric_b:
                # Compare numerically
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif is_numeric_a:
                # Numeric identifier has lower precedence than non-numeric
                return -1
            elif is_numeric_b:
                # Non-numeric identifier has higher precedence than numeric
                return 1
            else:
                # Compare as strings (ASCII order)
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major, minor, patch
    if major_a < major_b:
        return -1
    elif major_a > major_b:
        return 1

    if minor_a < minor_b:
        return -1
    elif minor_a > minor_b:
        return 1

    if patch_a < patch_b:
        return -1
    elif patch_a > patch_b:
        return 1

    # Compare pre-release
    return compare_prerelease(pre_a, pre_b)
